#include <vector>
#include <set>
#include <list>

void sequence_erase() {
    std::vector<int> v = {1, 2, 3, 4, 5};
    // Erase elements 2 and 3
    auto it = v.erase(v.begin() + 1, v.begin() + 3); 
    // it now points to the element '4'
}

void associative_erase() {
    std::set<int> s = {1, 2, 3, 4, 5};
    // Range erase returns void (pre-C++11/17 standard for range erase)
    s.erase(s.find(2), s.find(4)); 
    // auto it = s.erase(...) would be a compile error
}
